// Writes src/skills/builtin.gen.ts from the folders in skills/: Myrel's built-in skills, bundled
// into the Worker so they reach turns without being stored anywhere. Run it after changing a
// built-in skill; `--check` (part of typecheck) fails when the generated file is out of date.
//
//   pnpm --filter @myrel/api builtin-skills

import { readdir, readFile, writeFile } from "node:fs/promises";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../skills/", import.meta.url));
const out = fileURLToPath(new URL("../src/skills/builtin.gen.ts", import.meta.url));

async function files(dir) {
  const list = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) list.push(...(await files(path)));
    else list.push(path);
  }
  return list;
}

const skills = [];
for (const entry of (await readdir(root, { withFileTypes: true })).filter((e) => e.isDirectory()).sort((a, b) => a.name.localeCompare(b.name))) {
  const dir = join(root, entry.name);
  const list = (await files(dir)).map((f) => relative(dir, f).split("\\").join("/")).sort((a, b) => (a === "SKILL.md" ? -1 : b === "SKILL.md" ? 1 : a.localeCompare(b)));
  const contents = [];
  for (const path of list) contents.push({ path, content: await readFile(join(dir, path), "utf8") });
  skills.push({ name: entry.name, files: contents });
}

const body = [
  "// Generated by scripts/builtin-skills.mjs from apps/api/skills; do not edit by hand.",
  "// After changing a built-in skill run: pnpm --filter @myrel/api builtin-skills",
  "",
  "/** Each built-in skill's files as text, SKILL.md first. */",
  `export const BUILTIN_SKILL_FILES: Record<string, { path: string; content: string }[]> = ${JSON.stringify(Object.fromEntries(skills.map((s) => [s.name, s.files])), null, 2)};`,
  "",
].join("\n");

if (process.argv.includes("--check")) {
  const current = await readFile(out, "utf8").catch(() => "");
  if (current !== body) {
    console.error("src/skills/builtin.gen.ts is out of date with apps/api/skills: run `pnpm --filter @myrel/api builtin-skills`.");
    process.exit(1);
  }
} else {
  await writeFile(out, body);
  console.log(`Wrote ${relative(process.cwd(), out)} (${skills.map((s) => `${s.name}: ${s.files.length} files`).join(", ")})`);
}
